import java.util.*;
import java.io.*;

public class Main {
    static int[][][][] distArr = new int[15][15][15][15];
    static int[][] flowCap = new int[400][400];
    static char[][] scienceGrid = new char[20][20];
    static char[][] reactionGrid = new char[20][20];
    static int[] dirX = {1, 0, -1, 0};
    static int[] dirY = {0, 1, 0, -1};
    static int currentIteration = 3;
    static int[] visitedNodes = new int[400];
    static int nSize, maxTime;
    static int[][] reachMap = new int[13][13];
    static int[][] tempReachMap = new int[13][13];

    static int findAugment(int cnode, int dest, int bneck) {
        if (cnode == dest) return bneck;
        if (visitedNodes[cnode] == currentIteration) return 0;
        visitedNodes[cnode] = currentIteration;
        for (int i = 0; i <= dest; i++) {
            if (flowCap[cnode][i] > 0) {
                int pushedFlow = findAugment(i, dest, Math.min(bneck, flowCap[cnode][i]));
                if (pushedFlow > 0) {
                    flowCap[cnode][i] -= pushedFlow;
                    flowCap[i][cnode] += pushedFlow;
                    return pushedFlow;
                }
            }
        }
        return 0;
    }

    static int nodeNumber(int x, int y) {
        return (x - 1) * nSize + y - 1;
    }

    static void spread(int val) {
        for (int i = 1; i <= nSize; i++)
            for (int j = 1; j <= nSize; j++)
                tempReachMap[i][j] = reachMap[i][j];

        for (int i = 1; i <= nSize; i++) {
            for (int j = 1; j <= nSize; j++) {
                if (tempReachMap[i][j] == val) {
                    for (int d = 0; d < 4; d++) {
                        int ni = i + dirX[d], nj = j + dirY[d];
                        if (ni > 0 && nj > 0 && ni <= nSize && nj <= nSize && reachMap[ni][nj] < val && scienceGrid[ni][nj] != 'Y') {
                            reachMap[ni][nj] = val;
                        }
                    }
                }
            }
        }
    }

    static boolean checkReach(int sx, int sy, int tx, int ty, int ix, int iy) {
        for (int[] row : reachMap) Arrays.fill(row, 0);
        reachMap[sx][sy] = 1;
        reachMap[ix][iy] = 2;
        for (int i = 0; i < 100; i++) {
            spread(1);
            if (reachMap[tx][ty] == 1) return true;
            spread(2);
            if (reachMap[tx][ty] == 2) return false;
        }
        return false;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int infX = 0, infY = 0;
        for (int[][] arr2D : distArr)
            for (int[] arr1D : arr2D)
                Arrays.fill(arr1D, 1000000000);
        nSize = Integer.parseInt(st.nextToken());
        maxTime = Integer.parseInt(st.nextToken());

        for (int i = 1; i <= nSize; i++) {
            String line = br.readLine();
            for (int j = 1; j <= nSize; j++) {
                scienceGrid[i][j] = line.charAt(j - 1);
                distArr[i][j][i][j] = 0;
                if (scienceGrid[i][j] == 'Z') {
                    infX = i;
                    infY = j;
                }
            }
        }

        for (int i = 1; i <= nSize; i++) {
            String line = br.readLine();
            for (int j = 1; j <= nSize; j++) {
                reactionGrid[i][j] = line.charAt(j - 1);
            }
        }

        for (int i = 1; i <= nSize; i++) {
            for (int j = 1; j <= nSize; j++) {
                for (int d = 0; d < 4; d++) {
                    int ni = i + dirX[d], nj = j + dirY[d];
                    if (ni > 0 && ni <= nSize && nj > 0 && nj <= nSize) {
                        if (scienceGrid[i][j] != 'Y' && scienceGrid[ni][nj] != 'Y') {
                            distArr[i][j][ni][nj] = 1;
                        }
                    }
                }
            }
        }

        for (int ki = 1; ki <= nSize; ki++) {
            for (int kj = 1; kj <= nSize; kj++) {
                for (int ii = 1; ii <= nSize; ii++) {
                    for (int ij = 1; ij <= nSize; ij++) {
                        for (int ji = 1; ji <= nSize; ji++) {
                            for (int jj = 1; jj <= nSize; jj++) {
                                distArr[ii][ij][ji][jj] = Math.min(
                                    distArr[ii][ij][ji][jj],
                                    distArr[ii][ij][ki][kj] + distArr[ki][kj][ji][jj]
                                );
                            }
                        }
                    }
                }
            }
        }

        int srcNode = nSize * nSize * 2 + 1;
        int sinkNode = nSize * nSize * 2 + 2;

        for (int i = 1; i <= nSize; i++) {
            for (int j = 1; j <= nSize; j++) {
                if (Character.isDigit(scienceGrid[i][j])) {
                    flowCap[srcNode][nodeNumber(i, j)] = scienceGrid[i][j] - '0';
                }
                if (Character.isDigit(reactionGrid[i][j])) {
                    flowCap[nSize * nSize + nodeNumber(i, j)][sinkNode] = reactionGrid[i][j] - '0';
                }
                if (Character.isDigit(scienceGrid[i][j])) {
                    for (int ki = 1; ki <= nSize; ki++) {
                        for (int kj = 1; kj <= nSize; kj++) {
                            if (scienceGrid[i][j] > '0' && reactionGrid[ki][kj] > '0') {
                                if (Character.isDigit(reactionGrid[ki][kj]) && distArr[i][j][ki][kj] <= maxTime && checkReach(i, j, ki, kj, infX, infY)) {
                                    flowCap[nodeNumber(i, j)][nSize * nSize + nodeNumber(ki, kj)] = 1000;
                                }
                            }
                        }
                    }
                }
            }
        }

        int totalFlow = 0, flowVal;
        while ((flowVal = findAugment(srcNode, sinkNode, 1000)) > 0) {
            totalFlow += flowVal;
            currentIteration++;
        }

        System.out.println(totalFlow);
    }
}
